from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'docs/exercise-reference'
sources=[('KP01','Bodylastics','Guide exercices avec tubes','https://storage.googleapis.com/msgsndr/XvPdGEgSd8SLZjFiaiaQ/media/678d836801b601124c15cda0.pdf','Chest Press p.71 et Standing One Arm Chest Fly p.77','Ancrage bas à hauteur des genoux dans la poussée ; montage unilatéral deux extrémités sur une poignée. Pas notice Decathlon.'),('KP02','Tribe Fitness','Workout Guide 2018','https://v.fastcdn.co/u/82010628/33435656-0-TRIBE-WORKOUT-GUIDE-.pdf','Standing single sided chest fly p.6, Standing chest press p.7','Ancrages bas/milieu/haut et montage deux extrémités sur une poignée lus. Bras droit versus léger pli Tempo ; doses et squeeze maximal non importés. Capture PDF échouée.'),('KP03','Jim Stoppani','Build Your Chest With Resistance Bands','https://www.jimstoppani.com/training/build-your-chest-with-resistance-bands','Standing incline/decline press et one-arm flye','Procédures et souffle de famille. Développé descendant ancrage au-dessus tête et fin devant bas poitrine. Niveaux, doses et promesses régionales non adoptés.'),('KP04','XBAR Fitness','Resistance Band Chest Workout Guide','https://xbar.com/blogs/news/the-ultimate-resistance-band-chest-workout-guide','Anchor Height = Exercise Angle','Ancrages bas/haut pour incliné/décliné, soutien de famille ; ne valide pas réglages fins ni gains musculaires régionaux.'),('KP05','Thera-Band / Hygenic','Instruction Manual 2012','https://www.tumbltrak.com/content/pdf/Assembly_Instructions/TheraBand_User_Guide.pdf','Horizontal Adduction p.22','Unilatéral et absence de rotation, mais prise directe/bras droit différent des poignées et léger pli de Tempo.')]
registry=[dict(id=i,publisher=p,title=t,url=u,accessed='2026-10-12',consultedSection=s,limits=l) for i,p,t,u,s,l in sources]
refs={'EX75':['KP01','KP02','KP03','KP04'],'EX76':['KP02','KP03','KP04'],'EX77':['KP01','KP02','KP03','KP05']};records=[]
for e in json.loads((ROOT/'catalog/kit-exercises.json').read_text())['exercises']:
 if e['id'] not in refs:continue
 records.append(dict(id=e['id'],name=e['name'],minimumLevelProposed=e['minimumLevel'],documentaryStatus='prototype_editorial_with_variant_limits_not_human_validated',source_ids=refs[e['id']],positions=e['steps'],muscles=e['muscles'],muscleEvidence='Pectoraux et participation épaules/triceps qualitatifs, stabilisateurs = synthèse anatomique. Aucun pourcentage ou promesse régionale.',counting=e['counting'],sides=e['sides'],equipment=e['equipmentRequirements'],bandMount=e['bandMount'],prerequisites=['Montage maîtrisé et conforme à la notice.','Mouvement contrôlé à faible résistance, sans rotation ni cambrure forcée.'],errorsAndCorrections=e['errors'],remainingUnresolved=e['constraints'],evidenceByDomain={'positions':'Procédures exactes ou famille explicitées dans sources.limits, géométrie fine éditoriale.','muscles':'Qualitatif et inférences, carte sans validation anatomique humaine.','advice':'Retour contrôlé, absence de rotation et fixation recoupés ; sortie et limites du kit réel non homologuées.','media':'Deux poses image_gen, pas démonstration continue ni revue humaine.','audio':'Consignes textuelles avec voix système, clips F1/M2 non produits et écoute humaine non faite.'},media={'status':'generated_illustrations_unreviewed','source':'assets/sources/kit-expansion/'+e['id']+'.png','humanReview':None},audioDraft={'preparation':e['preparationCue'],'breathing':e['breathing'],'status':'system_voice_fallback'},localPrototypeIntegration={'status':'integrated_illustrated_prototype','humanTechnicalReview':None}))
obj={'sources':registry,'exercises':records,'method':'Compléments de direction et latéralité, pas promesse d’isoler une région ni preuve de supériorité hypertrophique. Les prescriptions restent des hypothèses Tempo. Les notices des autres marques ne certifient pas le kit réel. Captures PDF non accessibles non déclarées examinées.'}
(D/'kit-pectorals.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
lines=['# Trois compléments pectoraux avec kit','',''+obj['method'],'']
for e in records:lines+=['## '+e['id']+' - '+e['name'],'','Niveau éditorial : '+e['minimumLevelProposed']+'. Comptage : '+('par côté, deux côtés prévus' if e['sides']==2 else 'total par série')+'.',*['\n'+s['title']+' : '+s['description'] for s in e['positions']],'','Sources : '+', '.join(e['source_ids'])+'. Revue humaine, entrée/sortie, longueur/allongement réels, programmation et trajectoire continue restent ouverts.','']
lines+=['## Documents consultés','']+[f'- {s["id"]} [{s["publisher"]} - {s["title"]}]({s["url"]}) : {s["consultedSection"]}. {s["limits"]}' for s in registry]
(D/'kit-pectorals.md').write_text('\n'.join(lines)+'\n')
